#!/usr/bin/env bash
# Hardware: searchable user picker on Allocate/Reassign Asset. Generated
# by gen_deploy_user_combobox.py - do not hand-edit.
#
# Run this from the repo root on the server.
set -uo pipefail

sec() { echo ""; echo "=== $* ==="; echo "=== $* ===" >&2; }

FAIL=0

sec "0. Confirm repo root"
if [ ! -d "frontend/app/pages/hardware" ]; then
    echo "!!! frontend/app/pages/hardware not found under $(pwd) - run this from the repo root."
    exit 1
fi

sec "1. Pre-flight: verify both touched files are exactly what was confirmed"
if [ ! -f "frontend/app/pages/hardware/components/asset-transfer-dialog.tsx" ]; then
    echo "!!! frontend/app/pages/hardware/components/asset-transfer-dialog.tsx not found - aborting, nothing written yet."
    FAIL=1
else
    h=$(git hash-object "frontend/app/pages/hardware/components/asset-transfer-dialog.tsx")
    if [ "$h" != "277298f667fc991825fefef1d42cb8a040331d77" ]; then
        echo "!!! frontend/app/pages/hardware/components/asset-transfer-dialog.tsx does not match the expected pre-deploy hash."
        echo "    expected: 277298f667fc991825fefef1d42cb8a040331d77"
        echo "    actual:   $h"
        echo "    This file has changed on the server since it was last verified - do not proceed."
        FAIL=1
    fi
fi

if [ ! -f "frontend/components/shared/lookup-combobox.tsx" ]; then
    echo "!!! frontend/components/shared/lookup-combobox.tsx not found - aborting, nothing written yet."
    FAIL=1
else
    h=$(git hash-object "frontend/components/shared/lookup-combobox.tsx")
    if [ "$h" != "c1a4f4f8a02454ee21fb3cbda02868e2108f3cbd" ]; then
        echo "!!! frontend/components/shared/lookup-combobox.tsx does not match the expected pre-deploy hash."
        echo "    expected: c1a4f4f8a02454ee21fb3cbda02868e2108f3cbd"
        echo "    actual:   $h"
        echo "    This file has changed on the server since it was last verified - do not proceed."
        FAIL=1
    fi
fi

if [ "$FAIL" != "0" ]; then
    echo ""
    echo ">>> Pre-flight checks failed - nothing was written. See messages above."
    exit 1
fi
echo "All pre-flight checks passed."

sec "2. Writing files"
mkdir -p "$(dirname "frontend/app/pages/hardware/components/asset-transfer-dialog.tsx")"
base64 -d > "frontend/app/pages/hardware/components/asset-transfer-dialog.tsx.tmp" <<'B64EOF'

B64EOF
mv "frontend/app/pages/hardware/components/asset-transfer-dialog.tsx.tmp" "frontend/app/pages/hardware/components/asset-transfer-dialog.tsx"
echo "wrote frontend/app/pages/hardware/components/asset-transfer-dialog.tsx"

mkdir -p "$(dirname "frontend/components/shared/lookup-combobox.tsx")"
base64 -d > "frontend/components/shared/lookup-combobox.tsx.tmp" <<'B64EOF'

B64EOF
mv "frontend/components/shared/lookup-combobox.tsx.tmp" "frontend/components/shared/lookup-combobox.tsx"
echo "wrote frontend/components/shared/lookup-combobox.tsx"

sec "3. Post-flight: verify every written file matches the expected final hash"
POSTFAIL=0
h=$(git hash-object "frontend/app/pages/hardware/components/asset-transfer-dialog.tsx")
if [ "$h" != "0adb51ce05b6642bfb15700863c903954e8ef84e" ]; then
    echo "!!! frontend/app/pages/hardware/components/asset-transfer-dialog.tsx does not match the expected post-deploy hash (expected 0adb51ce05b6642bfb15700863c903954e8ef84e, got $h)"
    POSTFAIL=1
else
    echo "OK: frontend/app/pages/hardware/components/asset-transfer-dialog.tsx"
fi
h=$(git hash-object "frontend/components/shared/lookup-combobox.tsx")
if [ "$h" != "2d33227eb715f7c764a9ad9918b989642a77c350" ]; then
    echo "!!! frontend/components/shared/lookup-combobox.tsx does not match the expected post-deploy hash (expected 2d33227eb715f7c764a9ad9918b989642a77c350, got $h)"
    POSTFAIL=1
else
    echo "OK: frontend/components/shared/lookup-combobox.tsx"
fi

if [ "$POSTFAIL" != "0" ]; then
    echo ""
    echo ">>> Post-deploy verification failed - do not restart the frontend; investigate before proceeding."
    exit 1
fi

sec "4. Done"
echo "Both files written and verified. Next steps:"
echo "  1. git add -A && git commit  (commit this on the server's own checkout)"
echo "  2. docker compose build frontend && docker compose up -d frontend"
echo "  3. Open Hardware Assets, click Allocate (or Reassign) on any asset, and confirm the User field is now a search box - type a few letters of a name and confirm it filters"
echo "  4. Confirm picking a user still works and the dialog still submits normally"
echo "  5. Confirm the Software Inventory form's Entity/Department/Client pickers (which already used this same LookupCombobox) still show their \"None\" option - only the Hardware User field should have it hidden"
echo ">>> DONE"
